def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K moves through empty cells without visiting a cell twice.

    Paths may start at any empty cell and use the four orthogonal directions.
    The starting cell is included in the K+1 distinct cells of each path.

    Args:
        H: Number of rows (1 <= H <= 10).
        W: Number of columns (1 <= W <= 10).
        K: Number of moves (1 <= K <= 11).
        grid: H strings of length W, with '.' empty and '#' blocked.

    Returns:
        The number of valid paths of length K+1.

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = {
        (r, c): i
        for i, (r, c) in enumerate(
            (r, c)
            for r in range(H)
            for c in range(W)
            if grid[r][c] == '.'
        )
    }
    if len(cells) <= K:
        return 0

    neighbors = [[] for _ in cells]
    for (r, c), i in cells.items():
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = cells.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def dfs(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        visited[cell] = True
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                total += dfs(nxt, remaining - 1)
        visited[cell] = False
        return total

    return sum(dfs(start, K) for start in range(len(cells)))

