from functools import lru_cache


@lru_cache(maxsize=None)
def _nonzero_completions(remaining: int, digit_sum: int, digit_product: int) -> int:
    """Count beautiful completions using only nonzero digits."""
    if remaining == 0:
        return int(digit_sum > 0 and digit_product % digit_sum == 0)
    return sum(
        _nonzero_completions(remaining - 1, digit_sum + digit, digit_product * digit)
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = [int(char) for char in str(bound)]
    length = len(digits)
    nonzero_count = sum(9 ** size for size in range(1, length))
    beautiful_nonzero = sum(
        _nonzero_completions(size, 0, 1) for size in range(1, length)
    )

    digit_sum = 0
    digit_product = 1
    for index, limit in enumerate(digits):
        remaining = length - index - 1
        for digit in range(1, limit):
            nonzero_count += 9 ** remaining
            beautiful_nonzero += _nonzero_completions(
                remaining, digit_sum + digit, digit_product * digit
            )
        if limit == 0:
            break
        digit_sum += limit
        digit_product *= limit
    else:
        nonzero_count += 1
        beautiful_nonzero += int(digit_product % digit_sum == 0)

    # Every positive integer containing a zero has digit product zero.
    return bound - nonzero_count + beautiful_nonzero


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

