from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any coin denomination.

    Coins cannot be combined across denominations. There are 1-15 distinct
    positive denominations, each at most 25, and 1 <= k <= 2 * 10**9.
    """
    # Multiples of an already retained denomination add no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # Collect inclusion-exclusion coefficients by subset LCM. Equal LCMs
    # can be combined, since their contributions to every prefix are equal.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            additions[common] = additions.get(common, 0) - coefficient
        for multiple, coefficient in additions.items():
            value = coefficients.get(multiple, 0) + coefficient
            if value:
                coefficients[multiple] = value
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    low, high = 1, denominations[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # A denomination divisible by a smaller one contributes no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    low, high = denominations[0], denominations[0] * k
    # Group inclusion-exclusion terms with the same least common multiple.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common = divisor // gcd(divisor, coin) * coin
            if common <= high:
                changes[common] = changes.get(common, 0) - coefficient
        for divisor, coefficient in changes.items():
            coefficients[divisor] = coefficients.get(divisor, 0) + coefficient
            if coefficients[divisor] == 0:
                del coefficients[divisor]

    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in coefficients.items())
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

